"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

from datetime import date, datetime, timedelta

_MONTH_NAMES = {
    "jan": 1,
    "feb": 2,
    "mar": 3,
    "apr": 4,
    "may": 5,
    "jun": 6,
    "jul": 7,
    "aug": 8,
    "sep": 9,
    "oct": 10,
    "nov": 11,
    "dec": 12,
}

_WEEKDAY_NAMES = {
    "sun": 0,
    "mon": 1,
    "tue": 2,
    "wed": 3,
    "thu": 4,
    "fri": 5,
    "sat": 6,
}


def _parse_value(text, low, high, names, field):
    if not text:
        raise ValueError("empty value in %s field" % field)
    key = text.lower()
    if names is not None and key in names:
        return names[key]
    if not text.isdigit():
        raise ValueError("invalid value %r in %s field" % (text, field))
    value = int(text)
    if value < low or value > high:
        raise ValueError(
            "value %d out of range %d-%d in %s field"
            % (value, low, high, field)
        )
    return value


def _parse_step(text, field):
    if not text or not text.isdigit():
        raise ValueError("invalid step %r in %s field" % (text, field))
    step = int(text)
    if step < 1:
        raise ValueError("step must be positive in %s field" % field)
    return step


def _parse_item(item, low, high, names, field):
    if not item:
        raise ValueError("empty item in %s field" % field)
    if item.count("/") > 1:
        raise ValueError("malformed item %r in %s field" % (item, field))

    if "/" in item:
        base, step_text = item.split("/")
        step = _parse_step(step_text, field)
    else:
        base = item
        step = None

    if base == "*":
        if step is None:
            step = 1
        return set(range(low, high + 1, step))

    if "-" in base:
        if base.count("-") != 1:
            raise ValueError("malformed range %r in %s field" % (base, field))
        first, last = base.split("-")
        start = _parse_value(first, low, high, names, field)
        end = _parse_value(last, low, high, names, field)
        if start > end:
            raise ValueError(
                "reversed range %r in %s field" % (base, field)
            )
        if step is None:
            step = 1
        return set(range(start, end + 1, step))

    value = _parse_value(base, low, high, names, field)
    if step is None:
        return {value}
    return set(range(value, high + 1, step))


def _parse_field(raw, low, high, names, field):
    values = set()
    for item in raw.split(","):
        values.update(_parse_item(item, low, high, names, field))
    return values


def _add_years(value, years):
    try:
        return value.replace(year=value.year + years)
    except ValueError:
        # February 29 in a target year that is not a leap year.
        return value.replace(year=value.year + years, day=28)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(
            "expected five fields in cron expression, got %d" % len(fields)
        )

    minute_raw, hour_raw, dom_raw, month_raw, dow_raw = fields

    minutes = _parse_field(minute_raw, 0, 59, None, "minute")
    hours = _parse_field(hour_raw, 0, 23, None, "hour")
    days_of_month = _parse_field(dom_raw, 1, 31, None, "day of month")
    months = _parse_field(
        month_raw, 1, 12, _MONTH_NAMES, "month"
    )
    days_of_week = {
        value % 7
        for value in _parse_field(
            dow_raw, 0, 7, _WEEKDAY_NAMES, "day of week"
        )
    }

    dom_restricted = dom_raw != "*"
    dow_restricted = dow_raw != "*"

    # The first candidate is the next whole minute, which is always strictly
    # after ``after`` (even when its seconds and microseconds are nonzero).
    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = _add_years(after, 5)
    last_day = limit.date()

    ordered_hours = sorted(hours)
    ordered_minutes = sorted(minutes)

    day = start.date()
    while day <= last_day:
        if day.month not in months:
            # Skip the rest of this month.
            if day.month == 12:
                day = date(day.year + 1, 1, 1)
            else:
                day = date(day.year, day.month + 1, 1)
            continue

        weekday = (day.weekday() + 1) % 7
        dom_match = day.day in days_of_month
        dow_match = weekday in days_of_week
        if dom_restricted and dow_restricted:
            day_matches = dom_match or dow_match
        else:
            day_matches = dom_match and dow_match

        if day_matches:
            for hour in ordered_hours:
                for minute in ordered_minutes:
                    candidate = datetime(
                        day.year, day.month, day.day, hour, minute
                    )
                    if candidate >= start:
                        if candidate > limit:
                            raise ValueError(
                                "no matching time within five years"
                            )
                        return candidate

        day += timedelta(days=1)

    raise ValueError("no matching time within five years")

import random
import sys
from datetime import datetime, timedelta

sys.path.insert(0, "/private/tmp/tmpk3yoxvvh/pete/projects/devkit")

from devkit.cron import next_run

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}
DAYS = {"sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6}


def ref_value(tok, lo, hi, names):
    low = tok.lower()
    if low in names:
        return names[low]
    v = int(tok)
    if not lo <= v <= hi:
        raise ValueError(tok)
    return v


def ref_single_item(item, lo, hi, names):
    if "/" in item:
        base, step_s = item.split("/")
        step = int(step_s)
    else:
        base, step = item, 1
    if base == "*":
        return set(range(lo, hi + 1, step))
    if "-" in base:
        a_s, b_s = base.split("-")
        a = ref_value(a_s, lo, hi, names)
        b = ref_value(b_s, lo, hi, names)
    else:
        a = ref_value(base, lo, hi, names)
        b = a if "/" not in item else hi
    return set(range(a, b + 1, step))


def ref_parse(expr):
    parts = expr.split()
    assert len(parts) == 5, expr
    specs = [
        (parts[0], 0, 59, {}),
        (parts[1], 0, 23, {}),
        (parts[2], 1, 31, {}),
        (parts[3], 1, 12, MONTHS),
        (parts[4], 0, 7, DAYS),
    ]
    out = []
    for raw, lo, hi, names in specs:
        vals = set()
        for item in raw.split(","):
            vals |= ref_single_item(item, lo, hi, names)
        out.append(vals)
    return parts, out


def ref_match(expr, moment):
    parts, (mins, hrs, doms, months, dows) = ref_parse(expr)
    dows = {v % 7 for v in dows}
    if moment.minute not in mins or moment.hour not in hrs:
        return False
    if moment.month not in months:
        return False
    dom_ok = moment.day in doms
    dow_ok = (moment.weekday() + 1) % 7 in dows
    if parts[2] != "*" and parts[4] != "*":
        return dom_ok or dow_ok
    return dom_ok and dow_ok


def ref_next(expr, after, horizon_days=370):
    cur = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    stop = after + timedelta(days=horizon_days)
    while cur <= stop:
        if ref_match(expr, cur):
            return cur
        cur += timedelta(minutes=1)
    return None


def rand_item(rng, lo, hi, names, allow_names):
    kind = rng.choice(["star", "value", "range"])
    if kind == "star":
        base = "*"
    elif kind == "value":
        if allow_names and rng.random() < 0.3:
            base = rng.choice(list(names)).upper()
        else:
            base = str(rng.randint(lo, hi))
    else:
        if allow_names and rng.random() < 0.3:
            keys = list(names)
            a, b = sorted(rng.sample(keys, 2), key=lambda k: names[k])
            base = "%s-%s" % (a.upper(), b.upper())
        else:
            a, b = sorted((rng.randint(lo, hi), rng.randint(lo, hi)))
            base = "%d-%d" % (a, b)
    if rng.random() < 0.4:
        step = rng.choice([1, 2, 3, 4, 5, 6, 7, 10, 15, 20, 30, 100])
        base += "/%d" % step
    return base


def rand_field(rng, lo, hi, names=None, allow_names=False):
    names = names or {}
    n = rng.choice([1, 1, 1, 2])
    return ",".join(
        rand_item(rng, lo, hi, names, allow_names) for _ in range(n)
    )


rng = random.Random(20261027)
checked = 0
skipped = 0
for _ in range(120):
    expr = " ".join(
        [
            rand_field(rng, 0, 59),
            rand_field(rng, 0, 23),
            rand_field(rng, 1, 31),
            rand_field(rng, 1, 12, MONTHS, True),
            rand_field(rng, 0, 7, DAYS, True),
        ]
    )
    base = datetime(2023, 1, 1) + timedelta(
        days=rng.uniform(0, 1100), seconds=rng.uniform(0, 60),
        microseconds=rng.uniform(0, 1_000_000),
    )
    expected = ref_next(expr, base)
    if expected is None:
        skipped += 1
        continue
    got = next_run(expr, base)
    assert got == expected, (expr, base, got, expected)
    assert got > base
    assert got.second == 0 and got.microsecond == 0
    # One minute earlier must either be at/before the input or not match.
    earlier = got - timedelta(minutes=1)
    assert earlier <= base or not ref_match(expr, earlier), (expr, base, got)
    checked += 1

print("fuzz cases compared: %d (skipped no-match in 370 days: %d)"
      % (checked, skipped))
assert checked >= 80
print("fuzz assertions passed")
